-- =============================================================================
-- Migration 0038: K.2 Theorie B — Herhaald partieel integreren
-- =============================================================================
-- Gegenereerd door scripts/k2b-content.ts — niet met de hand bewerken.
--
-- Theorieblok B van K.2: twee keer achter elkaar partieel integreren. Dat
-- gebeurt in twee gedaanten: een veelterm van graad 2 zakt per ronde een graad,
-- en bij een e-macht maal een gonio komt de oorspronkelijke integraal na twee
-- rondes terug — die haal je naar een kant en deel je weg.
--
-- Eigen oefenvragen, geen boekopgaven. Elke primitieve wordt nagerekend door
-- src/content/primitieven.test.ts (content/hoofdstuk-k/k2b.json).
--
-- Alleen toevoegen: geen DELETE, DROP, ALTER of UPDATE. Twee keer draaien
-- voegt niets dubbel toe.
--
--   • 1 hoofdstuk, 3 topics, 6 clusters
--   • 36 vragen met elk 4 stappen (144 stappen)
-- =============================================================================

BEGIN;

-- 1. Hoofdstuk
INSERT INTO public.chapters (slug, title, book_part, order_index, site)
VALUES ('k', $ksql$K — Voortgezette integraalrekening$ksql$, 4, 12, 'integralen')
ON CONFLICT (slug) DO NOTHING;

-- 2. Topics
INSERT INTO public.topics_new (slug, title, chapter_id, order_index, is_unlocked_by_default, site, category)
SELECT v.slug, v.title, (SELECT id FROM public.chapters WHERE slug = 'k' AND site = 'integralen'), v.order_index, true, 'integralen', v.category
FROM (VALUES
  ('k2b_herhaald', $ksql$Twee keer partieel integreren$ksql$, 13, 'primitiveren'),
  ('k2b_bepaald', $ksql$Bepaalde integralen met herhaald partieel integreren$ksql$, 14, 'integralen'),
  ('k2b_toepassingen', $ksql$Oppervlakte met herhaald partieel integreren$ksql$, 15, 'toepassingen')
) AS v(slug, title, order_index, category)
ON CONFLICT (slug) DO NOTHING;

-- 3. Clusters
INSERT INTO public.topic_clusters_new (topic_id, slug, title, order_index, site)
SELECT t.id, v.slug, v.title, v.order_index, 'integralen'
FROM (VALUES
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Een veelterm van graad 2 maal een sinus of cosinus$ksql$, 1),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Een veelterm van graad 2 maal een e-macht$ksql$, 2),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$De integraal komt terug$ksql$, 3),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bepaalde integralen met twee rondes$ksql$, 1),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bepaalde integralen waarbij de integraal terugkomt$ksql$, 2),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Oppervlakte en p bepalen$ksql$, 1)
) AS v(topic_slug, slug, title, order_index)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
ON CONFLICT (topic_id, slug) DO NOTHING;

