  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{-x}\,\mathrm{d}x$$ksql$, $ksql$2 - 5/e$ksql$, $ksql$2 - \dfrac{5}{\mathrm{e}}$ksql$, 3, 6, ARRAY[$ksql$2 - 5e^(-1)$ksql$, $ksql$-5/e + 2$ksql$]::text[]),
