  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} \mathrm{e}^{2x}\sin(x)\,\mathrm{d}x$$ksql$, $ksql$1/5 (e^(2pi) + 1)$ksql$, $ksql$\tfrac{1}{5}\left(\mathrm{e}^{2\pi} + 1\right)$ksql$, 2, 3, ARRAY[$ksql$(e^(2pi) + 1)/5$ksql$]::text[]),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \mathrm{e}^{x}\cos(2x)\,\mathrm{d}x$$ksql$, $ksql$1/5 (2e^(pi/4) - 1)$ksql$, $ksql$\tfrac{1}{5}\left(2\mathrm{e}^{\frac{1}{4}\pi} - 1\right)$ksql$, 2, 4, ARRAY[$ksql$(2e^(pi/4) - 1)/5$ksql$]::text[]),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} \mathrm{e}^{-x}\sin(2x)\,\mathrm{d}x$$ksql$, $ksql$2/5 (1 - e^(-pi))$ksql$, $ksql$\tfrac{2}{5}\left(1 - \mathrm{e}^{-\pi}\right)$ksql$, 3, 5, ARRAY[$ksql$(2 - 2e^(-pi))/5$ksql$, $ksql$2/5 - 2/(5e^pi)$ksql$]::text[]),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \mathrm{e}^{3x}\cos(2x)\,\mathrm{d}x$$ksql$, $ksql$1/13 (2e^(3pi/4) - 3)$ksql$, $ksql$\tfrac{1}{13}\left(2\mathrm{e}^{\frac{3}{4}\pi} - 3\right)$ksql$, 3, 6, ARRAY[$ksql$(2e^(3pi/4) - 3)/13$ksql$]::text[]),
