-- 5. Stappen (step_order 0 t/m 3)
INSERT INTO public.question_steps_new (question_id, step_order, step_description)
SELECT vr.id, v.step_order, v.step_description
FROM (VALUES
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\sin(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een veelterm van graad 2 maal een sinus of cosinus → partieel integreren. Differentiëren haalt de graad van de veelterm één omlaag, dus na één ronde staat er nog een product van graad 1: dan moet je een tweede keer partieel integreren.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\sin(x)$$ksql$, 1, $ksql$Noem de factor die je eerst primitiveert $h'$ en de andere $g$: $h'(x) = \sin(x)$, dus $h(x) = -\cos(x)$, en $g(x) = x^{2}$, dus $g'(x) = 2x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\sin(x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int x^{2}\sin(x)\,\mathrm{d}x = -x^{2}\cos(x) + \int 2x\cos(x)\,\mathrm{d}x$. Er staat nog een product, dus dit is nog niet klaar.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\sin(x)$$ksql$, 3, $ksql$Tweede ronde op $\int 2x\cos(x)\,\mathrm{d}x$: nu is $h'(x) = \cos(x)$, dus $h(x) = \sin(x)$, en $g(x) = 2x$, dus $g'(x) = 2$. Dat geeft $2x\sin(x) - \int 2\sin(x)\,\mathrm{d}x = 2x\sin(x) + 2\cos(x)$. Samen: $F(x) = -x^{2}\cos(x) + 2x\sin(x) + 2\cos(x) + c$. Controle: differentiëren geeft $-2x\cos(x) + x^{2}\sin(x) + 2\sin(x) + 2x\cos(x) - 2\sin(x) = x^{2}\sin(x)$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\cos(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een veelterm van graad 2 maal een sinus of cosinus → partieel integreren. Differentiëren haalt de graad van de veelterm één omlaag, dus na één ronde staat er nog een product van graad 1: dan moet je een tweede keer partieel integreren.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\cos(x)$$ksql$, 1, $ksql$Noem de factor die je eerst primitiveert $h'$ en de andere $g$: $h'(x) = \cos(x)$, dus $h(x) = \sin(x)$, en $g(x) = x^{2}$, dus $g'(x) = 2x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\cos(x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int x^{2}\cos(x)\,\mathrm{d}x = x^{2}\sin(x) - \int 2x\sin(x)\,\mathrm{d}x$. De overgebleven integraal is nog steeds een product, maar wel één graad eenvoudiger.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\cos(x)$$ksql$, 3, $ksql$Tweede ronde op $\int 2x\sin(x)\,\mathrm{d}x$: $h'(x) = \sin(x)$, dus $h(x) = -\cos(x)$, en $g(x) = 2x$, dus $g'(x) = 2$. Dat geeft $-2x\cos(x) + \int 2\cos(x)\,\mathrm{d}x = -2x\cos(x) + 2\sin(x)$. Let op het minteken ervoor: $F(x) = x^{2}\sin(x) + 2x\cos(x) - 2\sin(x) + c$. Controle: differentiëren geeft $2x\sin(x) + x^{2}\cos(x) + 2\cos(x) - 2x\sin(x) - 2\cos(x) = x^{2}\cos(x)$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\sin(2x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een veelterm van graad 2 maal een sinus of cosinus → partieel integreren. Differentiëren haalt de graad van de veelterm één omlaag, dus na één ronde staat er nog een product van graad 1: dan moet je een tweede keer partieel integreren.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\sin(2x)$$ksql$, 1, $ksql$Noem $h'(x) = \sin(2x)$, dus $h(x) = -\tfrac{1}{2}\cos(2x)$ — door de $2$ in de hoek komt er een $\tfrac{1}{2}$ bij — en $g(x) = x^{2}$, dus $g'(x) = 2x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\sin(2x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int x^{2}\sin(2x)\,\mathrm{d}x = -\tfrac{1}{2}x^{2}\cos(2x) + \int \tfrac{1}{2}\cos(2x) \cdot 2x\,\mathrm{d}x = -\tfrac{1}{2}x^{2}\cos(2x) + \int x\cos(2x)\,\mathrm{d}x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\sin(2x)$$ksql$, 3, $ksql$Tweede ronde op $\int x\cos(2x)\,\mathrm{d}x$: $h'(x) = \cos(2x)$, dus $h(x) = \tfrac{1}{2}\sin(2x)$, en $g(x) = x$, dus $g'(x) = 1$. Dat geeft $\tfrac{1}{2}x\sin(2x) - \int \tfrac{1}{2}\sin(2x)\,\mathrm{d}x = \tfrac{1}{2}x\sin(2x) + \tfrac{1}{4}\cos(2x)$. Samen: $F(x) = -\tfrac{1}{2}x^{2}\cos(2x) + \tfrac{1}{2}x\sin(2x) + \tfrac{1}{4}\cos(2x) + c$. Controle: differentiëren geeft $-x\cos(2x) + x^{2}\sin(2x) + \tfrac{1}{2}\sin(2x) + x\cos(2x) - \tfrac{1}{2}\sin(2x) = x^{2}\sin(2x)$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = \left(x^{2} + 4x\right)\cos(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een veelterm van graad 2 maal een sinus of cosinus → partieel integreren. Differentiëren haalt de graad van de veelterm één omlaag, dus na één ronde staat er nog een product van graad 1: dan moet je een tweede keer partieel integreren.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = \left(x^{2} + 4x\right)\cos(x)$$ksql$, 1, $ksql$De hele haakjesterm gaat in één keer mee als $g$; uitvermenigvuldigen hoeft niet. Noem $h'(x) = \cos(x)$, dus $h(x) = \sin(x)$, en $g(x) = x^{2} + 4x$, dus $g'(x) = 2x + 4$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = \left(x^{2} + 4x\right)\cos(x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \left(x^{2} + 4x\right)\cos(x)\,\mathrm{d}x = \left(x^{2} + 4x\right)\sin(x) - \int (2x + 4)\sin(x)\,\mathrm{d}x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = \left(x^{2} + 4x\right)\cos(x)$$ksql$, 3, $ksql$Tweede ronde op $\int (2x + 4)\sin(x)\,\mathrm{d}x$: $h'(x) = \sin(x)$, dus $h(x) = -\cos(x)$, en $g(x) = 2x + 4$, dus $g'(x) = 2$. Dat geeft $-(2x + 4)\cos(x) + \int 2\cos(x)\,\mathrm{d}x = -(2x + 4)\cos(x) + 2\sin(x)$. Met het minteken ervoor: $F(x) = \left(x^{2} + 4x\right)\sin(x) + (2x + 4)\cos(x) - 2\sin(x) + c$. Controle: differentiëren geeft $(2x + 4)\sin(x) + \left(x^{2} + 4x\right)\cos(x) + 2\cos(x) - (2x + 4)\sin(x) - 2\cos(x) = \left(x^{2} + 4x\right)\cos(x)$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\cos(3x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een veelterm van graad 2 maal een sinus of cosinus → partieel integreren. Differentiëren haalt de graad van de veelterm één omlaag, dus na één ronde staat er nog een product van graad 1: dan moet je een tweede keer partieel integreren.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\cos(3x)$$ksql$, 1, $ksql$Noem $h'(x) = \cos(3x)$, dus $h(x) = \tfrac{1}{3}\sin(3x)$, en $g(x) = x^{2}$, dus $g'(x) = 2x$. Elke ronde levert door de $3$ in de hoek weer een factor $\tfrac{1}{3}$ op; daar komen de noemers $3$, $9$ en $27$ vandaan.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\cos(3x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int x^{2}\cos(3x)\,\mathrm{d}x = \tfrac{1}{3}x^{2}\sin(3x) - \int \tfrac{1}{3}\sin(3x) \cdot 2x\,\mathrm{d}x = \tfrac{1}{3}x^{2}\sin(3x) - \tfrac{2}{3}\int x\sin(3x)\,\mathrm{d}x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\cos(3x)$$ksql$, 3, $ksql$Tweede ronde op $\int x\sin(3x)\,\mathrm{d}x$: $h'(x) = \sin(3x)$, dus $h(x) = -\tfrac{1}{3}\cos(3x)$, en $g(x) = x$, dus $g'(x) = 1$. Dat geeft $-\tfrac{1}{3}x\cos(3x) + \int \tfrac{1}{3}\cos(3x)\,\mathrm{d}x = -\tfrac{1}{3}x\cos(3x) + \tfrac{1}{9}\sin(3x)$. Vermenigvuldig met $-\tfrac{2}{3}$ en tel op: $F(x) = \tfrac{1}{3}x^{2}\sin(3x) + \tfrac{2}{9}x\cos(3x) - \tfrac{2}{27}\sin(3x) + c$. Controle: differentiëren geeft $\tfrac{2}{3}x\sin(3x) + x^{2}\cos(3x) + \tfrac{2}{9}\cos(3x) - \tfrac{2}{3}x\sin(3x) - \tfrac{2}{9}\cos(3x) = x^{2}\cos(3x)$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = \left(x^{2} - x\right)\sin(2x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een veelterm van graad 2 maal een sinus of cosinus → partieel integreren. Differentiëren haalt de graad van de veelterm één omlaag, dus na één ronde staat er nog een product van graad 1: dan moet je een tweede keer partieel integreren.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = \left(x^{2} - x\right)\sin(2x)$$ksql$, 1, $ksql$Noem $h'(x) = \sin(2x)$, dus $h(x) = -\tfrac{1}{2}\cos(2x)$, en $g(x) = x^{2} - x$, dus $g'(x) = 2x - 1$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = \left(x^{2} - x\right)\sin(2x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \left(x^{2} - x\right)\sin(2x)\,\mathrm{d}x = -\tfrac{1}{2}\left(x^{2} - x\right)\cos(2x) + \int \tfrac{1}{2}\cos(2x)(2x - 1)\,\mathrm{d}x = -\tfrac{1}{2}\left(x^{2} - x\right)\cos(2x) + \int \left(x - \tfrac{1}{2}\right)\cos(2x)\,\mathrm{d}x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = \left(x^{2} - x\right)\sin(2x)$$ksql$, 3, $ksql$Tweede ronde op $\int \left(x - \tfrac{1}{2}\right)\cos(2x)\,\mathrm{d}x$: $h'(x) = \cos(2x)$, dus $h(x) = \tfrac{1}{2}\sin(2x)$, en $g(x) = x - \tfrac{1}{2}$, dus $g'(x) = 1$. Dat geeft $\left(\tfrac{1}{2}x - \tfrac{1}{4}\right)\sin(2x) - \int \tfrac{1}{2}\sin(2x)\,\mathrm{d}x = \left(\tfrac{1}{2}x - \tfrac{1}{4}\right)\sin(2x) + \tfrac{1}{4}\cos(2x)$. Samen: $F(x) = -\tfrac{1}{2}\left(x^{2} - x\right)\cos(2x) + \left(\tfrac{1}{2}x - \tfrac{1}{4}\right)\sin(2x) + \tfrac{1}{4}\cos(2x) + c$. Controle: differentiëren laat alle $\cos(2x)$- en losse $\sin(2x)$-termen wegvallen en houdt $\left(x^{2} - x\right)\sin(2x)$ over.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = x^{2}\mathrm{e}^{x}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een veelterm van graad 2 maal een e-macht → partieel integreren. De e-macht verandert nauwelijks, maar de veelterm zakt per ronde één graad. Van graad 2 naar graad 0 zijn dat twee rondes.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = x^{2}\mathrm{e}^{x}$$ksql$, 1, $ksql$Noem de factor die je eerst primitiveert $h'$ en de andere $g$: $h'(x) = \mathrm{e}^{x}$, dus $h(x) = \mathrm{e}^{x}$, en $g(x) = x^{2}$, dus $g'(x) = 2x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = x^{2}\mathrm{e}^{x}$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int x^{2}\mathrm{e}^{x}\,\mathrm{d}x = x^{2}\mathrm{e}^{x} - \int 2x\mathrm{e}^{x}\,\mathrm{d}x$. Er staat nog een product, dus nog een ronde.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = x^{2}\mathrm{e}^{x}$$ksql$, 3, $ksql$Tweede ronde op $\int 2x\mathrm{e}^{x}\,\mathrm{d}x$: $h'(x) = \mathrm{e}^{x}$ en $g(x) = 2x$, dus $g'(x) = 2$. Dat geeft $2x\mathrm{e}^{x} - \int 2\mathrm{e}^{x}\,\mathrm{d}x = 2x\mathrm{e}^{x} - 2\mathrm{e}^{x}$. Samen: $F(x) = x^{2}\mathrm{e}^{x} - 2x\mathrm{e}^{x} + 2\mathrm{e}^{x} = \left(x^{2} - 2x + 2\right)\mathrm{e}^{x} + c$. Controle: differentiëren geeft $(2x - 2)\mathrm{e}^{x} + \left(x^{2} - 2x + 2\right)\mathrm{e}^{x} = x^{2}\mathrm{e}^{x}$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = x^{2}\mathrm{e}^{2x}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een veelterm van graad 2 maal een e-macht → partieel integreren. De e-macht verandert nauwelijks, maar de veelterm zakt per ronde één graad. Van graad 2 naar graad 0 zijn dat twee rondes.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = x^{2}\mathrm{e}^{2x}$$ksql$, 1, $ksql$Noem $h'(x) = \mathrm{e}^{2x}$, dus $h(x) = \tfrac{1}{2}\mathrm{e}^{2x}$ — door de $2$ in de exponent komt er een $\tfrac{1}{2}$ bij — en $g(x) = x^{2}$, dus $g'(x) = 2x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = x^{2}\mathrm{e}^{2x}$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int x^{2}\mathrm{e}^{2x}\,\mathrm{d}x = \tfrac{1}{2}x^{2}\mathrm{e}^{2x} - \int \tfrac{1}{2}\mathrm{e}^{2x} \cdot 2x\,\mathrm{d}x = \tfrac{1}{2}x^{2}\mathrm{e}^{2x} - \int x\mathrm{e}^{2x}\,\mathrm{d}x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = x^{2}\mathrm{e}^{2x}$$ksql$, 3, $ksql$Tweede ronde op $\int x\mathrm{e}^{2x}\,\mathrm{d}x$: $h'(x) = \mathrm{e}^{2x}$, dus $h(x) = \tfrac{1}{2}\mathrm{e}^{2x}$, en $g(x) = x$, dus $g'(x) = 1$. Dat geeft $\tfrac{1}{2}x\mathrm{e}^{2x} - \int \tfrac{1}{2}\mathrm{e}^{2x}\,\mathrm{d}x = \tfrac{1}{2}x\mathrm{e}^{2x} - \tfrac{1}{4}\mathrm{e}^{2x}$. Samen: $F(x) = \tfrac{1}{2}x^{2}\mathrm{e}^{2x} - \tfrac{1}{2}x\mathrm{e}^{2x} + \tfrac{1}{4}\mathrm{e}^{2x} + c$. Controle: differentiëren geeft $x\mathrm{e}^{2x} + x^{2}\mathrm{e}^{2x} - \tfrac{1}{2}\mathrm{e}^{2x} - x\mathrm{e}^{2x} + \tfrac{1}{2}\mathrm{e}^{2x} = x^{2}\mathrm{e}^{2x}$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = \left(x^{2} + 3\right)\mathrm{e}^{x}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een veelterm van graad 2 maal een e-macht → partieel integreren. De e-macht verandert nauwelijks, maar de veelterm zakt per ronde één graad. Van graad 2 naar graad 0 zijn dat twee rondes.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = \left(x^{2} + 3\right)\mathrm{e}^{x}$$ksql$, 1, $ksql$De hele haakjesterm is $g$: $g(x) = x^{2} + 3$, dus $g'(x) = 2x$ — de $3$ valt bij het differentiëren weg. En $h'(x) = \mathrm{e}^{x}$, dus $h(x) = \mathrm{e}^{x}$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = \left(x^{2} + 3\right)\mathrm{e}^{x}$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \left(x^{2} + 3\right)\mathrm{e}^{x}\,\mathrm{d}x = \left(x^{2} + 3\right)\mathrm{e}^{x} - \int 2x\mathrm{e}^{x}\,\mathrm{d}x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = \left(x^{2} + 3\right)\mathrm{e}^{x}$$ksql$, 3, $ksql$Tweede ronde op $\int 2x\mathrm{e}^{x}\,\mathrm{d}x = 2x\mathrm{e}^{x} - 2\mathrm{e}^{x}$. Dus $F(x) = \left(x^{2} + 3\right)\mathrm{e}^{x} - 2x\mathrm{e}^{x} + 2\mathrm{e}^{x} = \left(x^{2} - 2x + 5\right)\mathrm{e}^{x} + c$. Controle: differentiëren geeft $(2x - 2)\mathrm{e}^{x} + \left(x^{2} - 2x + 5\right)\mathrm{e}^{x} = \left(x^{2} + 3\right)\mathrm{e}^{x}$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = 3x^{2}\mathrm{e}^{-x}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een veelterm van graad 2 maal een e-macht → partieel integreren. De e-macht verandert nauwelijks, maar de veelterm zakt per ronde één graad. Van graad 2 naar graad 0 zijn dat twee rondes.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = 3x^{2}\mathrm{e}^{-x}$$ksql$, 1, $ksql$Noem $h'(x) = \mathrm{e}^{-x}$, dus $h(x) = -\mathrm{e}^{-x}$ — door de $-1$ in de exponent draait het teken om — en $g(x) = 3x^{2}$, dus $g'(x) = 6x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = 3x^{2}\mathrm{e}^{-x}$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int 3x^{2}\mathrm{e}^{-x}\,\mathrm{d}x = -3x^{2}\mathrm{e}^{-x} + \int 6x\mathrm{e}^{-x}\,\mathrm{d}x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = 3x^{2}\mathrm{e}^{-x}$$ksql$, 3, $ksql$Tweede ronde op $\int 6x\mathrm{e}^{-x}\,\mathrm{d}x$: $h'(x) = \mathrm{e}^{-x}$, dus $h(x) = -\mathrm{e}^{-x}$, en $g(x) = 6x$, dus $g'(x) = 6$. Dat geeft $-6x\mathrm{e}^{-x} + \int 6\mathrm{e}^{-x}\,\mathrm{d}x = -6x\mathrm{e}^{-x} - 6\mathrm{e}^{-x}$. Samen: $F(x) = -\left(3x^{2} + 6x + 6\right)\mathrm{e}^{-x} + c$. Controle: differentiëren geeft $-(6x + 6)\mathrm{e}^{-x} + \left(3x^{2} + 6x + 6\right)\mathrm{e}^{-x} = 3x^{2}\mathrm{e}^{-x}$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = \left(x^{2} - 4x\right)\mathrm{e}^{2x}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een veelterm van graad 2 maal een e-macht → partieel integreren. De e-macht verandert nauwelijks, maar de veelterm zakt per ronde één graad. Van graad 2 naar graad 0 zijn dat twee rondes.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = \left(x^{2} - 4x\right)\mathrm{e}^{2x}$$ksql$, 1, $ksql$Noem $h'(x) = \mathrm{e}^{2x}$, dus $h(x) = \tfrac{1}{2}\mathrm{e}^{2x}$, en $g(x) = x^{2} - 4x$, dus $g'(x) = 2x - 4$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = \left(x^{2} - 4x\right)\mathrm{e}^{2x}$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \left(x^{2} - 4x\right)\mathrm{e}^{2x}\,\mathrm{d}x = \tfrac{1}{2}\left(x^{2} - 4x\right)\mathrm{e}^{2x} - \int \tfrac{1}{2}\mathrm{e}^{2x}(2x - 4)\,\mathrm{d}x = \tfrac{1}{2}\left(x^{2} - 4x\right)\mathrm{e}^{2x} - \int (x - 2)\mathrm{e}^{2x}\,\mathrm{d}x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = \left(x^{2} - 4x\right)\mathrm{e}^{2x}$$ksql$, 3, $ksql$Tweede ronde op $\int (x - 2)\mathrm{e}^{2x}\,\mathrm{d}x$: $h'(x) = \mathrm{e}^{2x}$, dus $h(x) = \tfrac{1}{2}\mathrm{e}^{2x}$, en $g(x) = x - 2$, dus $g'(x) = 1$. Dat geeft $\tfrac{1}{2}(x - 2)\mathrm{e}^{2x} - \tfrac{1}{4}\mathrm{e}^{2x}$. Trek dat ervan af en neem $\mathrm{e}^{2x}$ buiten haakjes: $F(x) = \left(\tfrac{1}{2}x^{2} - 2x - \tfrac{1}{2}x + 1 + \tfrac{1}{4}\right)\mathrm{e}^{2x} = \left(\tfrac{1}{2}x^{2} - \tfrac{5}{2}x + \tfrac{5}{4}\right)\mathrm{e}^{2x} + c$. Controle: differentiëren geeft $\left(x - \tfrac{5}{2}\right)\mathrm{e}^{2x} + \left(x^{2} - 5x + \tfrac{5}{2}\right)\mathrm{e}^{2x} = \left(x^{2} - 4x\right)\mathrm{e}^{2x}$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = \dfrac{x^{2}}{\mathrm{e}^{3x}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Herschrijf eerst: een e-macht in de noemer is een e-macht met een minteken in de exponent, dus $f(x) = x^{2}\mathrm{e}^{-3x}$. Buitenste schil: een veelterm van graad 2 maal een e-macht → partieel integreren. De e-macht verandert nauwelijks, maar de veelterm zakt per ronde één graad. Van graad 2 naar graad 0 zijn dat twee rondes.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = \dfrac{x^{2}}{\mathrm{e}^{3x}}$$ksql$, 1, $ksql$Noem $h'(x) = \mathrm{e}^{-3x}$, dus $h(x) = -\tfrac{1}{3}\mathrm{e}^{-3x}$, en $g(x) = x^{2}$, dus $g'(x) = 2x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = \dfrac{x^{2}}{\mathrm{e}^{3x}}$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int x^{2}\mathrm{e}^{-3x}\,\mathrm{d}x = -\tfrac{1}{3}x^{2}\mathrm{e}^{-3x} + \int \tfrac{1}{3}\mathrm{e}^{-3x} \cdot 2x\,\mathrm{d}x = -\tfrac{1}{3}x^{2}\mathrm{e}^{-3x} + \tfrac{2}{3}\int x\mathrm{e}^{-3x}\,\mathrm{d}x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = \dfrac{x^{2}}{\mathrm{e}^{3x}}$$ksql$, 3, $ksql$Tweede ronde op $\int x\mathrm{e}^{-3x}\,\mathrm{d}x = -\tfrac{1}{3}x\mathrm{e}^{-3x} + \int \tfrac{1}{3}\mathrm{e}^{-3x}\,\mathrm{d}x = -\tfrac{1}{3}x\mathrm{e}^{-3x} - \tfrac{1}{9}\mathrm{e}^{-3x}$. Vermenigvuldig met $\tfrac{2}{3}$ en tel op: $F(x) = -\tfrac{1}{3}x^{2}\mathrm{e}^{-3x} - \tfrac{2}{9}x\mathrm{e}^{-3x} - \tfrac{2}{27}\mathrm{e}^{-3x} = -\tfrac{1}{27}\left(9x^{2} + 6x + 2\right)\mathrm{e}^{-3x} + c$. Controle: differentiëren geeft $-\tfrac{1}{27}(18x + 6)\mathrm{e}^{-3x} + \tfrac{1}{9}\left(9x^{2} + 6x + 2\right)\mathrm{e}^{-3x} = x^{2}\mathrm{e}^{-3x}$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{x}\sin(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een e-macht maal een sinus of cosinus → partieel integreren. Geen van beide factoren wordt eenvoudiger, dus dit loopt niet vanzelf af. Doe toch twee rondes: dan staat de oorspronkelijke integraal er weer, en kun je hem naar één kant halen.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{x}\sin(x)$$ksql$, 1, $ksql$Kies $h'(x) = \mathrm{e}^{x}$, dus $h(x) = \mathrm{e}^{x}$, en $g(x) = \sin(x)$, dus $g'(x) = \cos(x)$. Houd die keuze in de tweede ronde vol: primitiveer weer de e-macht, anders draai je alles terug en staat er $I = I$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{x}\sin(x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Eerste ronde: $I = \int \mathrm{e}^{x}\sin(x)\,\mathrm{d}x = \mathrm{e}^{x}\sin(x) - \int \mathrm{e}^{x}\cos(x)\,\mathrm{d}x$. Tweede ronde op die laatste integraal, met $h'(x) = \mathrm{e}^{x}$ en $g(x) = \cos(x)$, dus $g'(x) = -\sin(x)$: $\int \mathrm{e}^{x}\cos(x)\,\mathrm{d}x = \mathrm{e}^{x}\cos(x) + \int \mathrm{e}^{x}\sin(x)\,\mathrm{d}x = \mathrm{e}^{x}\cos(x) + I$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{x}\sin(x)$$ksql$, 3, $ksql$Noem de gevraagde integraal $I$. Na twee rondes staat $I$ rechts ook weer, dus je lost $I$ op zoals een vergelijking: alles met $I$ naar links, daarna delen. Invullen geeft $I = \mathrm{e}^{x}\sin(x) - \mathrm{e}^{x}\cos(x) - I$, dus $2I = \mathrm{e}^{x}\left(\sin(x) - \cos(x)\right)$ en $F(x) = \tfrac{1}{2}\mathrm{e}^{x}\left(\sin(x) - \cos(x)\right) + c$. Controle: differentiëren geeft $\tfrac{1}{2}\mathrm{e}^{x}\left(\sin(x) - \cos(x)\right) + \tfrac{1}{2}\mathrm{e}^{x}\left(\cos(x) + \sin(x)\right) = \mathrm{e}^{x}\sin(x)$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{x}\cos(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een e-macht maal een sinus of cosinus → partieel integreren. Geen van beide factoren wordt eenvoudiger, dus dit loopt niet vanzelf af. Doe toch twee rondes: dan staat de oorspronkelijke integraal er weer, en kun je hem naar één kant halen.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{x}\cos(x)$$ksql$, 1, $ksql$Kies $h'(x) = \mathrm{e}^{x}$, dus $h(x) = \mathrm{e}^{x}$, en $g(x) = \cos(x)$, dus $g'(x) = -\sin(x)$. In de tweede ronde primitiveer je opnieuw de e-macht.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{x}\cos(x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Eerste ronde: $I = \int \mathrm{e}^{x}\cos(x)\,\mathrm{d}x = \mathrm{e}^{x}\cos(x) + \int \mathrm{e}^{x}\sin(x)\,\mathrm{d}x$. Tweede ronde op $\int \mathrm{e}^{x}\sin(x)\,\mathrm{d}x$, met $g(x) = \sin(x)$ en $g'(x) = \cos(x)$: dat is $\mathrm{e}^{x}\sin(x) - \int \mathrm{e}^{x}\cos(x)\,\mathrm{d}x = \mathrm{e}^{x}\sin(x) - I$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{x}\cos(x)$$ksql$, 3, $ksql$Noem de gevraagde integraal $I$. Na twee rondes staat $I$ rechts ook weer, dus je lost $I$ op zoals een vergelijking: alles met $I$ naar links, daarna delen. Invullen geeft $I = \mathrm{e}^{x}\cos(x) + \mathrm{e}^{x}\sin(x) - I$, dus $2I = \mathrm{e}^{x}\left(\sin(x) + \cos(x)\right)$ en $F(x) = \tfrac{1}{2}\mathrm{e}^{x}\left(\sin(x) + \cos(x)\right) + c$. Controle: differentiëren geeft $\tfrac{1}{2}\mathrm{e}^{x}\left(\sin(x) + \cos(x)\right) + \tfrac{1}{2}\mathrm{e}^{x}\left(\cos(x) - \sin(x)\right) = \mathrm{e}^{x}\cos(x)$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{2x}\sin(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een e-macht maal een sinus of cosinus → partieel integreren. Geen van beide factoren wordt eenvoudiger, dus dit loopt niet vanzelf af. Doe toch twee rondes: dan staat de oorspronkelijke integraal er weer, en kun je hem naar één kant halen.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{2x}\sin(x)$$ksql$, 1, $ksql$Kies $h'(x) = \mathrm{e}^{2x}$, dus $h(x) = \tfrac{1}{2}\mathrm{e}^{2x}$, en $g(x) = \sin(x)$, dus $g'(x) = \cos(x)$. Elke ronde levert een factor $\tfrac{1}{2}$ op; daarom komt $I$ straks met een kwart terug en blijft er $\tfrac{5}{4}$ over.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{2x}\sin(x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Eerste ronde: $I = \tfrac{1}{2}\mathrm{e}^{2x}\sin(x) - \tfrac{1}{2}\int \mathrm{e}^{2x}\cos(x)\,\mathrm{d}x$. Tweede ronde op $\int \mathrm{e}^{2x}\cos(x)\,\mathrm{d}x = \tfrac{1}{2}\mathrm{e}^{2x}\cos(x) + \tfrac{1}{2}\int \mathrm{e}^{2x}\sin(x)\,\mathrm{d}x = \tfrac{1}{2}\mathrm{e}^{2x}\cos(x) + \tfrac{1}{2}I$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{2x}\sin(x)$$ksql$, 3, $ksql$Noem de gevraagde integraal $I$. Na twee rondes staat $I$ rechts ook weer, dus je lost $I$ op zoals een vergelijking: alles met $I$ naar links, daarna delen. Invullen geeft $I = \tfrac{1}{2}\mathrm{e}^{2x}\sin(x) - \tfrac{1}{4}\mathrm{e}^{2x}\cos(x) - \tfrac{1}{4}I$, dus $\tfrac{5}{4}I = \tfrac{1}{4}\mathrm{e}^{2x}\left(2\sin(x) - \cos(x)\right)$ en $F(x) = \tfrac{1}{5}\mathrm{e}^{2x}\left(2\sin(x) - \cos(x)\right) + c$. Controle: differentiëren geeft $\tfrac{2}{5}\mathrm{e}^{2x}\left(2\sin(x) - \cos(x)\right) + \tfrac{1}{5}\mathrm{e}^{2x}\left(2\cos(x) + \sin(x)\right) = \mathrm{e}^{2x}\sin(x)$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{x}\cos(2x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een e-macht maal een sinus of cosinus → partieel integreren. Geen van beide factoren wordt eenvoudiger, dus dit loopt niet vanzelf af. Doe toch twee rondes: dan staat de oorspronkelijke integraal er weer, en kun je hem naar één kant halen.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{x}\cos(2x)$$ksql$, 1, $ksql$Kies $h'(x) = \mathrm{e}^{x}$, dus $h(x) = \mathrm{e}^{x}$, en $g(x) = \cos(2x)$, dus $g'(x) = -2\sin(2x)$. Door de $2$ in de hoek komt er bij elke ronde een factor $2$ bij; na twee rondes staat $I$ er dus met een $4$ voor.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{x}\cos(2x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Eerste ronde: $I = \mathrm{e}^{x}\cos(2x) + 2\int \mathrm{e}^{x}\sin(2x)\,\mathrm{d}x$. Tweede ronde op $\int \mathrm{e}^{x}\sin(2x)\,\mathrm{d}x$, met $g(x) = \sin(2x)$ en $g'(x) = 2\cos(2x)$: dat is $\mathrm{e}^{x}\sin(2x) - 2\int \mathrm{e}^{x}\cos(2x)\,\mathrm{d}x = \mathrm{e}^{x}\sin(2x) - 2I$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{x}\cos(2x)$$ksql$, 3, $ksql$Noem de gevraagde integraal $I$. Na twee rondes staat $I$ rechts ook weer, dus je lost $I$ op zoals een vergelijking: alles met $I$ naar links, daarna delen. Invullen geeft $I = \mathrm{e}^{x}\cos(2x) + 2\mathrm{e}^{x}\sin(2x) - 4I$, dus $5I = \mathrm{e}^{x}\left(\cos(2x) + 2\sin(2x)\right)$ en $F(x) = \tfrac{1}{5}\mathrm{e}^{x}\left(\cos(2x) + 2\sin(2x)\right) + c$. Controle: differentiëren geeft $\tfrac{1}{5}\mathrm{e}^{x}\left(\cos(2x) + 2\sin(2x)\right) + \tfrac{1}{5}\mathrm{e}^{x}\left(-2\sin(2x) + 4\cos(2x)\right) = \mathrm{e}^{x}\cos(2x)$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{-x}\sin(2x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een e-macht maal een sinus of cosinus → partieel integreren. Geen van beide factoren wordt eenvoudiger, dus dit loopt niet vanzelf af. Doe toch twee rondes: dan staat de oorspronkelijke integraal er weer, en kun je hem naar één kant halen.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{-x}\sin(2x)$$ksql$, 1, $ksql$Kies $h'(x) = \mathrm{e}^{-x}$, dus $h(x) = -\mathrm{e}^{-x}$, en $g(x) = \sin(2x)$, dus $g'(x) = 2\cos(2x)$. Let op twee dingen tegelijk: de e-macht draait van teken en de gonio levert een factor $2$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{-x}\sin(2x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Eerste ronde: $I = -\mathrm{e}^{-x}\sin(2x) + 2\int \mathrm{e}^{-x}\cos(2x)\,\mathrm{d}x$. Tweede ronde op $\int \mathrm{e}^{-x}\cos(2x)\,\mathrm{d}x$, met $g(x) = \cos(2x)$ en $g'(x) = -2\sin(2x)$: dat is $-\mathrm{e}^{-x}\cos(2x) - 2\int \mathrm{e}^{-x}\sin(2x)\,\mathrm{d}x = -\mathrm{e}^{-x}\cos(2x) - 2I$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{-x}\sin(2x)$$ksql$, 3, $ksql$Noem de gevraagde integraal $I$. Na twee rondes staat $I$ rechts ook weer, dus je lost $I$ op zoals een vergelijking: alles met $I$ naar links, daarna delen. Invullen geeft $I = -\mathrm{e}^{-x}\sin(2x) - 2\mathrm{e}^{-x}\cos(2x) - 4I$, dus $5I = -\mathrm{e}^{-x}\left(\sin(2x) + 2\cos(2x)\right)$ en $F(x) = -\tfrac{1}{5}\mathrm{e}^{-x}\left(\sin(2x) + 2\cos(2x)\right) + c$. Controle: differentiëren geeft $\tfrac{1}{5}\mathrm{e}^{-x}\left(\sin(2x) + 2\cos(2x)\right) - \tfrac{1}{5}\mathrm{e}^{-x}\left(2\cos(2x) - 4\sin(2x)\right) = \mathrm{e}^{-x}\sin(2x)$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{3x}\cos(2x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een e-macht maal een sinus of cosinus → partieel integreren. Geen van beide factoren wordt eenvoudiger, dus dit loopt niet vanzelf af. Doe toch twee rondes: dan staat de oorspronkelijke integraal er weer, en kun je hem naar één kant halen.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{3x}\cos(2x)$$ksql$, 1, $ksql$Kies $h'(x) = \mathrm{e}^{3x}$, dus $h(x) = \tfrac{1}{3}\mathrm{e}^{3x}$, en $g(x) = \cos(2x)$, dus $g'(x) = -2\sin(2x)$. Elke ronde levert $\tfrac{2}{3}$ op, dus na twee rondes staat $I$ er met $\tfrac{4}{9}$ bij.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{3x}\cos(2x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Eerste ronde: $I = \tfrac{1}{3}\mathrm{e}^{3x}\cos(2x) + \tfrac{2}{3}\int \mathrm{e}^{3x}\sin(2x)\,\mathrm{d}x$. Tweede ronde op $\int \mathrm{e}^{3x}\sin(2x)\,\mathrm{d}x = \tfrac{1}{3}\mathrm{e}^{3x}\sin(2x) - \tfrac{2}{3}\int \mathrm{e}^{3x}\cos(2x)\,\mathrm{d}x = \tfrac{1}{3}\mathrm{e}^{3x}\sin(2x) - \tfrac{2}{3}I$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{3x}\cos(2x)$$ksql$, 3, $ksql$Noem de gevraagde integraal $I$. Na twee rondes staat $I$ rechts ook weer, dus je lost $I$ op zoals een vergelijking: alles met $I$ naar links, daarna delen. Invullen geeft $I = \tfrac{1}{3}\mathrm{e}^{3x}\cos(2x) + \tfrac{2}{9}\mathrm{e}^{3x}\sin(2x) - \tfrac{4}{9}I$, dus $\tfrac{13}{9}I = \tfrac{1}{9}\mathrm{e}^{3x}\left(3\cos(2x) + 2\sin(2x)\right)$ en $F(x) = \tfrac{1}{13}\mathrm{e}^{3x}\left(3\cos(2x) + 2\sin(2x)\right) + c$. Controle: differentiëren geeft $\tfrac{3}{13}\mathrm{e}^{3x}\left(3\cos(2x) + 2\sin(2x)\right) + \tfrac{1}{13}\mathrm{e}^{3x}\left(-6\sin(2x) + 4\cos(2x)\right) = \mathrm{e}^{3x}\cos(2x)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} x^{2}\sin(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een veelterm van graad 2 maal een sinus of cosinus → partieel integreren. Differentiëren haalt de graad van de veelterm één omlaag, dus na één ronde staat er nog een product van graad 1: dan moet je een tweede keer partieel integreren.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} x^{2}\sin(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Eerste ronde met $h'(x) = \sin(x)$, dus $h(x) = -\cos(x)$, en $g(x) = x^{2}$, dus $g'(x) = 2x$: $\int x^{2}\sin(x)\,\mathrm{d}x = -x^{2}\cos(x) + \int 2x\cos(x)\,\mathrm{d}x$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} x^{2}\sin(x)\,\mathrm{d}x$$ksql$, 2, $ksql$Tweede ronde op $\int 2x\cos(x)\,\mathrm{d}x = 2x\sin(x) + 2\cos(x)$. De primitieve is dus $F(x) = -x^{2}\cos(x) + 2x\sin(x) + 2\cos(x)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} x^{2}\sin(x)\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in. Met $\cos(\pi) = -1$ en $\sin(\pi) = 0$ is $F(\pi) = \pi^{2} + 0 - 2 = \pi^{2} - 2$, en $F(0) = 0 + 0 + 2 = 2$. De integraal is $\left(\pi^{2} - 2\right) - 2 = \pi^{2} - 4$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{x}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een veelterm van graad 2 maal een e-macht → partieel integreren. De e-macht verandert nauwelijks, maar de veelterm zakt per ronde één graad. Van graad 2 naar graad 0 zijn dat twee rondes.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{x}\,\mathrm{d}x$$ksql$, 1, $ksql$Eerste ronde met $h'(x) = \mathrm{e}^{x}$ en $g(x) = x^{2}$, dus $g'(x) = 2x$: $\int x^{2}\mathrm{e}^{x}\,\mathrm{d}x = x^{2}\mathrm{e}^{x} - \int 2x\mathrm{e}^{x}\,\mathrm{d}x$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{x}\,\mathrm{d}x$$ksql$, 2, $ksql$Tweede ronde op $\int 2x\mathrm{e}^{x}\,\mathrm{d}x = 2x\mathrm{e}^{x} - 2\mathrm{e}^{x}$. De primitieve is dus $F(x) = \left(x^{2} - 2x + 2\right)\mathrm{e}^{x}$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{x}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $F(1) = (1 - 2 + 2)\mathrm{e} = \mathrm{e}$ en $F(0) = 2 \cdot 1 = 2$. De integraal is $\mathrm{e} - 2$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x^{2}\cos(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een veelterm van graad 2 maal een sinus of cosinus → partieel integreren. Differentiëren haalt de graad van de veelterm één omlaag, dus na één ronde staat er nog een product van graad 1: dan moet je een tweede keer partieel integreren.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x^{2}\cos(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Eerste ronde met $h'(x) = \cos(x)$, dus $h(x) = \sin(x)$, en $g(x) = x^{2}$, dus $g'(x) = 2x$: $\int x^{2}\cos(x)\,\mathrm{d}x = x^{2}\sin(x) - \int 2x\sin(x)\,\mathrm{d}x$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x^{2}\cos(x)\,\mathrm{d}x$$ksql$, 2, $ksql$Tweede ronde op $\int 2x\sin(x)\,\mathrm{d}x = -2x\cos(x) + 2\sin(x)$. De primitieve is dus $F(x) = x^{2}\sin(x) + 2x\cos(x) - 2\sin(x)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x^{2}\cos(x)\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in. Met $\sin\left(\tfrac{1}{2}\pi\right) = 1$ en $\cos\left(\tfrac{1}{2}\pi\right) = 0$ is $F\left(\tfrac{1}{2}\pi\right) = \tfrac{1}{4}\pi^{2} + 0 - 2$, en $F(0) = 0$. De integraal is $\tfrac{1}{4}\pi^{2} - 2$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{2x}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een veelterm van graad 2 maal een e-macht → partieel integreren. De e-macht verandert nauwelijks, maar de veelterm zakt per ronde één graad. Van graad 2 naar graad 0 zijn dat twee rondes.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{2x}\,\mathrm{d}x$$ksql$, 1, $ksql$Eerste ronde met $h'(x) = \mathrm{e}^{2x}$, dus $h(x) = \tfrac{1}{2}\mathrm{e}^{2x}$, en $g(x) = x^{2}$: $\int x^{2}\mathrm{e}^{2x}\,\mathrm{d}x = \tfrac{1}{2}x^{2}\mathrm{e}^{2x} - \int x\mathrm{e}^{2x}\,\mathrm{d}x$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{2x}\,\mathrm{d}x$$ksql$, 2, $ksql$Tweede ronde op $\int x\mathrm{e}^{2x}\,\mathrm{d}x = \tfrac{1}{2}x\mathrm{e}^{2x} - \tfrac{1}{4}\mathrm{e}^{2x}$. De primitieve is dus $F(x) = \tfrac{1}{2}x^{2}\mathrm{e}^{2x} - \tfrac{1}{2}x\mathrm{e}^{2x} + \tfrac{1}{4}\mathrm{e}^{2x}$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{2x}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $F(1) = \tfrac{1}{2}\mathrm{e}^{2} - \tfrac{1}{2}\mathrm{e}^{2} + \tfrac{1}{4}\mathrm{e}^{2} = \tfrac{1}{4}\mathrm{e}^{2}$ en $F(0) = \tfrac{1}{4}$. De integraal is $\tfrac{1}{4}\mathrm{e}^{2} - \tfrac{1}{4} = \tfrac{1}{4}\left(\mathrm{e}^{2} - 1\right)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x^{2}\sin(2x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een veelterm van graad 2 maal een sinus of cosinus → partieel integreren. Differentiëren haalt de graad van de veelterm één omlaag, dus na één ronde staat er nog een product van graad 1: dan moet je een tweede keer partieel integreren.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x^{2}\sin(2x)\,\mathrm{d}x$$ksql$, 1, $ksql$Eerste ronde met $h'(x) = \sin(2x)$, dus $h(x) = -\tfrac{1}{2}\cos(2x)$, en $g(x) = x^{2}$: $\int x^{2}\sin(2x)\,\mathrm{d}x = -\tfrac{1}{2}x^{2}\cos(2x) + \int x\cos(2x)\,\mathrm{d}x$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x^{2}\sin(2x)\,\mathrm{d}x$$ksql$, 2, $ksql$Tweede ronde op $\int x\cos(2x)\,\mathrm{d}x = \tfrac{1}{2}x\sin(2x) + \tfrac{1}{4}\cos(2x)$. De primitieve is dus $F(x) = -\tfrac{1}{2}x^{2}\cos(2x) + \tfrac{1}{2}x\sin(2x) + \tfrac{1}{4}\cos(2x)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x^{2}\sin(2x)\,\mathrm{d}x$$ksql$, 3, $ksql$Let op de dubbele hoek: bij $x = \tfrac{1}{2}\pi$ is $2x = \pi$, dus $\cos(2x) = -1$ en $\sin(2x) = 0$. Dan is $F\left(\tfrac{1}{2}\pi\right) = \tfrac{1}{8}\pi^{2} + 0 - \tfrac{1}{4}$, en $F(0) = \tfrac{1}{4}$. De integraal is $\tfrac{1}{8}\pi^{2} - \tfrac{1}{2}$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{-x}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een veelterm van graad 2 maal een e-macht → partieel integreren. De e-macht verandert nauwelijks, maar de veelterm zakt per ronde één graad. Van graad 2 naar graad 0 zijn dat twee rondes.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{-x}\,\mathrm{d}x$$ksql$, 1, $ksql$Eerste ronde met $h'(x) = \mathrm{e}^{-x}$, dus $h(x) = -\mathrm{e}^{-x}$, en $g(x) = x^{2}$, dus $g'(x) = 2x$: $\int x^{2}\mathrm{e}^{-x}\,\mathrm{d}x = -x^{2}\mathrm{e}^{-x} + \int 2x\mathrm{e}^{-x}\,\mathrm{d}x$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{-x}\,\mathrm{d}x$$ksql$, 2, $ksql$Tweede ronde op $\int 2x\mathrm{e}^{-x}\,\mathrm{d}x = -2x\mathrm{e}^{-x} - 2\mathrm{e}^{-x}$. De primitieve is dus $F(x) = -\left(x^{2} + 2x + 2\right)\mathrm{e}^{-x}$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{-x}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $F(1) = -(1 + 2 + 2)\mathrm{e}^{-1} = -\dfrac{5}{\mathrm{e}}$ en $F(0) = -2$. De integraal is $-\dfrac{5}{\mathrm{e}} + 2 = 2 - \dfrac{5}{\mathrm{e}}$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} \mathrm{e}^{x}\sin(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een e-macht maal een sinus of cosinus → partieel integreren. Geen van beide factoren wordt eenvoudiger, dus dit loopt niet vanzelf af. Doe toch twee rondes: dan staat de oorspronkelijke integraal er weer, en kun je hem naar één kant halen.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} \mathrm{e}^{x}\sin(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Kies $h'(x) = \mathrm{e}^{x}$ en $g(x) = \sin(x)$, en houd die keuze in de tweede ronde vol.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} \mathrm{e}^{x}\sin(x)\,\mathrm{d}x$$ksql$, 2, $ksql$Na twee rondes staat er $I = \mathrm{e}^{x}\sin(x) - \mathrm{e}^{x}\cos(x) - I$. Noem de gevraagde integraal $I$. Na twee rondes staat $I$ rechts ook weer, dus je lost $I$ op zoals een vergelijking: alles met $I$ naar links, daarna delen. Dat geeft $2I = \mathrm{e}^{x}\left(\sin(x) - \cos(x)\right)$, dus $F(x) = \tfrac{1}{2}\mathrm{e}^{x}\left(\sin(x) - \cos(x)\right)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} \mathrm{e}^{x}\sin(x)\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in. Met $\sin(\pi) = 0$ en $\cos(\pi) = -1$ is $F(\pi) = \tfrac{1}{2}\mathrm{e}^{\pi}(0 + 1) = \tfrac{1}{2}\mathrm{e}^{\pi}$, en $F(0) = \tfrac{1}{2}(0 - 1) = -\tfrac{1}{2}$. De integraal is $\tfrac{1}{2}\mathrm{e}^{\pi} + \tfrac{1}{2} = \tfrac{1}{2}\left(\mathrm{e}^{\pi} + 1\right)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \mathrm{e}^{x}\cos(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een e-macht maal een sinus of cosinus → partieel integreren. Geen van beide factoren wordt eenvoudiger, dus dit loopt niet vanzelf af. Doe toch twee rondes: dan staat de oorspronkelijke integraal er weer, en kun je hem naar één kant halen.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \mathrm{e}^{x}\cos(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Kies $h'(x) = \mathrm{e}^{x}$ en $g(x) = \cos(x)$, dus $g'(x) = -\sin(x)$, en houd die keuze vol.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \mathrm{e}^{x}\cos(x)\,\mathrm{d}x$$ksql$, 2, $ksql$Na twee rondes staat er $I = \mathrm{e}^{x}\cos(x) + \mathrm{e}^{x}\sin(x) - I$. Noem de gevraagde integraal $I$. Na twee rondes staat $I$ rechts ook weer, dus je lost $I$ op zoals een vergelijking: alles met $I$ naar links, daarna delen. Dat geeft $2I = \mathrm{e}^{x}\left(\sin(x) + \cos(x)\right)$, dus $F(x) = \tfrac{1}{2}\mathrm{e}^{x}\left(\sin(x) + \cos(x)\right)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \mathrm{e}^{x}\cos(x)\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in. Met $\sin\left(\tfrac{1}{2}\pi\right) = 1$ en $\cos\left(\tfrac{1}{2}\pi\right) = 0$ is $F\left(\tfrac{1}{2}\pi\right) = \tfrac{1}{2}\mathrm{e}^{\frac{1}{2}\pi}$, en $F(0) = \tfrac{1}{2}(0 + 1) = \tfrac{1}{2}$. De integraal is $\tfrac{1}{2}\mathrm{e}^{\frac{1}{2}\pi} - \tfrac{1}{2}$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} \mathrm{e}^{2x}\sin(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een e-macht maal een sinus of cosinus → partieel integreren. Geen van beide factoren wordt eenvoudiger, dus dit loopt niet vanzelf af. Doe toch twee rondes: dan staat de oorspronkelijke integraal er weer, en kun je hem naar één kant halen.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} \mathrm{e}^{2x}\sin(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Kies $h'(x) = \mathrm{e}^{2x}$, dus $h(x) = \tfrac{1}{2}\mathrm{e}^{2x}$, en $g(x) = \sin(x)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} \mathrm{e}^{2x}\sin(x)\,\mathrm{d}x$$ksql$, 2, $ksql$Na twee rondes staat er $I = \tfrac{1}{2}\mathrm{e}^{2x}\sin(x) - \tfrac{1}{4}\mathrm{e}^{2x}\cos(x) - \tfrac{1}{4}I$. Noem de gevraagde integraal $I$. Na twee rondes staat $I$ rechts ook weer, dus je lost $I$ op zoals een vergelijking: alles met $I$ naar links, daarna delen. Uit $\tfrac{5}{4}I = \tfrac{1}{4}\mathrm{e}^{2x}\left(2\sin(x) - \cos(x)\right)$ volgt $F(x) = \tfrac{1}{5}\mathrm{e}^{2x}\left(2\sin(x) - \cos(x)\right)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} \mathrm{e}^{2x}\sin(x)\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $F(\pi) = \tfrac{1}{5}\mathrm{e}^{2\pi}(0 + 1) = \tfrac{1}{5}\mathrm{e}^{2\pi}$ en $F(0) = \tfrac{1}{5}(0 - 1) = -\tfrac{1}{5}$. De integraal is $\tfrac{1}{5}\mathrm{e}^{2\pi} + \tfrac{1}{5} = \tfrac{1}{5}\left(\mathrm{e}^{2\pi} + 1\right)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \mathrm{e}^{x}\cos(2x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een e-macht maal een sinus of cosinus → partieel integreren. Geen van beide factoren wordt eenvoudiger, dus dit loopt niet vanzelf af. Doe toch twee rondes: dan staat de oorspronkelijke integraal er weer, en kun je hem naar één kant halen.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \mathrm{e}^{x}\cos(2x)\,\mathrm{d}x$$ksql$, 1, $ksql$Kies $h'(x) = \mathrm{e}^{x}$ en $g(x) = \cos(2x)$, dus $g'(x) = -2\sin(2x)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \mathrm{e}^{x}\cos(2x)\,\mathrm{d}x$$ksql$, 2, $ksql$Na twee rondes staat er $I = \mathrm{e}^{x}\cos(2x) + 2\mathrm{e}^{x}\sin(2x) - 4I$. Noem de gevraagde integraal $I$. Na twee rondes staat $I$ rechts ook weer, dus je lost $I$ op zoals een vergelijking: alles met $I$ naar links, daarna delen. Uit $5I = \mathrm{e}^{x}\left(\cos(2x) + 2\sin(2x)\right)$ volgt $F(x) = \tfrac{1}{5}\mathrm{e}^{x}\left(\cos(2x) + 2\sin(2x)\right)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \mathrm{e}^{x}\cos(2x)\,\mathrm{d}x$$ksql$, 3, $ksql$Bij $x = \tfrac{1}{4}\pi$ is $2x = \tfrac{1}{2}\pi$, dus $\cos(2x) = 0$ en $\sin(2x) = 1$: $F\left(\tfrac{1}{4}\pi\right) = \tfrac{2}{5}\mathrm{e}^{\frac{1}{4}\pi}$. En $F(0) = \tfrac{1}{5}(1 + 0) = \tfrac{1}{5}$. De integraal is $\tfrac{2}{5}\mathrm{e}^{\frac{1}{4}\pi} - \tfrac{1}{5} = \tfrac{1}{5}\left(2\mathrm{e}^{\frac{1}{4}\pi} - 1\right)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} \mathrm{e}^{-x}\sin(2x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een e-macht maal een sinus of cosinus → partieel integreren. Geen van beide factoren wordt eenvoudiger, dus dit loopt niet vanzelf af. Doe toch twee rondes: dan staat de oorspronkelijke integraal er weer, en kun je hem naar één kant halen.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} \mathrm{e}^{-x}\sin(2x)\,\mathrm{d}x$$ksql$, 1, $ksql$Kies $h'(x) = \mathrm{e}^{-x}$, dus $h(x) = -\mathrm{e}^{-x}$, en $g(x) = \sin(2x)$, dus $g'(x) = 2\cos(2x)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} \mathrm{e}^{-x}\sin(2x)\,\mathrm{d}x$$ksql$, 2, $ksql$Na twee rondes staat er $I = -\mathrm{e}^{-x}\sin(2x) - 2\mathrm{e}^{-x}\cos(2x) - 4I$. Noem de gevraagde integraal $I$. Na twee rondes staat $I$ rechts ook weer, dus je lost $I$ op zoals een vergelijking: alles met $I$ naar links, daarna delen. Uit $5I = -\mathrm{e}^{-x}\left(\sin(2x) + 2\cos(2x)\right)$ volgt $F(x) = -\tfrac{1}{5}\mathrm{e}^{-x}\left(\sin(2x) + 2\cos(2x)\right)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} \mathrm{e}^{-x}\sin(2x)\,\mathrm{d}x$$ksql$, 3, $ksql$Bij $x = \pi$ is $2x = 2\pi$, dus $\sin(2x) = 0$ en $\cos(2x) = 1$: $F(\pi) = -\tfrac{2}{5}\mathrm{e}^{-\pi}$. En $F(0) = -\tfrac{1}{5}(0 + 2) = -\tfrac{2}{5}$. De integraal is $-\tfrac{2}{5}\mathrm{e}^{-\pi} + \tfrac{2}{5} = \tfrac{2}{5}\left(1 - \mathrm{e}^{-\pi}\right)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \mathrm{e}^{3x}\cos(2x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een e-macht maal een sinus of cosinus → partieel integreren. Geen van beide factoren wordt eenvoudiger, dus dit loopt niet vanzelf af. Doe toch twee rondes: dan staat de oorspronkelijke integraal er weer, en kun je hem naar één kant halen.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \mathrm{e}^{3x}\cos(2x)\,\mathrm{d}x$$ksql$, 1, $ksql$Kies $h'(x) = \mathrm{e}^{3x}$, dus $h(x) = \tfrac{1}{3}\mathrm{e}^{3x}$, en $g(x) = \cos(2x)$, dus $g'(x) = -2\sin(2x)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \mathrm{e}^{3x}\cos(2x)\,\mathrm{d}x$$ksql$, 2, $ksql$Na twee rondes staat er $I = \tfrac{1}{3}\mathrm{e}^{3x}\cos(2x) + \tfrac{2}{9}\mathrm{e}^{3x}\sin(2x) - \tfrac{4}{9}I$. Noem de gevraagde integraal $I$. Na twee rondes staat $I$ rechts ook weer, dus je lost $I$ op zoals een vergelijking: alles met $I$ naar links, daarna delen. Uit $\tfrac{13}{9}I = \tfrac{1}{9}\mathrm{e}^{3x}\left(3\cos(2x) + 2\sin(2x)\right)$ volgt $F(x) = \tfrac{1}{13}\mathrm{e}^{3x}\left(3\cos(2x) + 2\sin(2x)\right)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \mathrm{e}^{3x}\cos(2x)\,\mathrm{d}x$$ksql$, 3, $ksql$Bij $x = \tfrac{1}{4}\pi$ is $2x = \tfrac{1}{2}\pi$, dus $\cos(2x) = 0$ en $\sin(2x) = 1$: $F\left(\tfrac{1}{4}\pi\right) = \tfrac{2}{13}\mathrm{e}^{\frac{3}{4}\pi}$. En $F(0) = \tfrac{3}{13}$. De integraal is $\tfrac{2}{13}\mathrm{e}^{\frac{3}{4}\pi} - \tfrac{3}{13} = \tfrac{1}{13}\left(2\mathrm{e}^{\frac{3}{4}\pi} - 3\right)$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x^{2}\mathrm{e}^{-x}$, de $x$-as, de $y$-as en de lijn $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1 van de driedeling: $x^{2}$ is nooit negatief en $\mathrm{e}^{-x}$ is altijd positief, dus de grafiek ligt op $[0, 2]$ boven de $x$-as. De oppervlakte is $\displaystyle\int_{0}^{2} x^{2}\mathrm{e}^{-x}\,\mathrm{d}x$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x^{2}\mathrm{e}^{-x}$, de $x$-as, de $y$-as en de lijn $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Deel 2: een veelterm van graad 2 maal een e-macht → twee keer partieel integreren. Eerste ronde met $h'(x) = \mathrm{e}^{-x}$, dus $h(x) = -\mathrm{e}^{-x}$, en $g(x) = x^{2}$, dus $g'(x) = 2x$: $\int x^{2}\mathrm{e}^{-x}\,\mathrm{d}x = -x^{2}\mathrm{e}^{-x} + \int 2x\mathrm{e}^{-x}\,\mathrm{d}x$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x^{2}\mathrm{e}^{-x}$, de $x$-as, de $y$-as en de lijn $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Tweede ronde op $\int 2x\mathrm{e}^{-x}\,\mathrm{d}x = -2x\mathrm{e}^{-x} - 2\mathrm{e}^{-x}$. De primitieve is $F(x) = -\left(x^{2} + 2x + 2\right)\mathrm{e}^{-x}$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x^{2}\mathrm{e}^{-x}$, de $x$-as, de $y$-as en de lijn $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Vul de grenzen in: $F(2) = -(4 + 4 + 2)\mathrm{e}^{-2} = -\dfrac{10}{\mathrm{e}^{2}}$ en $F(0) = -2$. De oppervlakte is $-\dfrac{10}{\mathrm{e}^{2}} + 2 = 2 - \dfrac{10}{\mathrm{e}^{2}}$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \left(x^{2} + 2x\right)\mathrm{e}^{x}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1 van de driedeling: $f(x) = x(x + 2)\mathrm{e}^{x}$ is nul bij $x = 0$ en $x = -2$, want $\mathrm{e}^{x}$ is nooit nul. De grafiek sluit samen met de lijn $x = 1$ het stuk tussen $x = 0$ en $x = 1$ in, en daar is $f$ positief. De oppervlakte is $\displaystyle\int_{0}^{1} \left(x^{2} + 2x\right)\mathrm{e}^{x}\,\mathrm{d}x$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \left(x^{2} + 2x\right)\mathrm{e}^{x}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Deel 2: een veelterm van graad 2 maal een e-macht → twee keer partieel integreren. Eerste ronde met $h'(x) = \mathrm{e}^{x}$ en $g(x) = x^{2} + 2x$, dus $g'(x) = 2x + 2$: $\int \left(x^{2} + 2x\right)\mathrm{e}^{x}\,\mathrm{d}x = \left(x^{2} + 2x\right)\mathrm{e}^{x} - \int (2x + 2)\mathrm{e}^{x}\,\mathrm{d}x$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \left(x^{2} + 2x\right)\mathrm{e}^{x}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Tweede ronde op $\int (2x + 2)\mathrm{e}^{x}\,\mathrm{d}x = (2x + 2)\mathrm{e}^{x} - \int 2\mathrm{e}^{x}\,\mathrm{d}x = (2x)\mathrm{e}^{x}$. Dus $F(x) = \left(x^{2} + 2x\right)\mathrm{e}^{x} - 2x\mathrm{e}^{x} = x^{2}\mathrm{e}^{x}$ — verrassend kort. Controle: differentiëren geeft $2x\mathrm{e}^{x} + x^{2}\mathrm{e}^{x} = \left(x^{2} + 2x\right)\mathrm{e}^{x}$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \left(x^{2} + 2x\right)\mathrm{e}^{x}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Vul de grenzen in: $F(1) = 1 \cdot \mathrm{e} = \mathrm{e}$ en $F(0) = 0$. De oppervlakte is $\mathrm{e}$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \mathrm{e}^{-x}\cos(x)$, de $x$-as en de $y$-as, op $\left[0, \tfrac{1}{2}\pi\right]$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1 van de driedeling: op $\left[0, \tfrac{1}{2}\pi\right]$ is $\cos(x) \geq 0$ en $\mathrm{e}^{-x} > 0$, dus de grafiek ligt boven de $x$-as; bij $x = \tfrac{1}{2}\pi$ raakt hij de $x$-as. De oppervlakte is $\displaystyle\int_{0}^{\frac{1}{2}\pi} \mathrm{e}^{-x}\cos(x)\,\mathrm{d}x$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \mathrm{e}^{-x}\cos(x)$, de $x$-as en de $y$-as, op $\left[0, \tfrac{1}{2}\pi\right]$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Deel 2: een e-macht maal een gonio → twee keer partieel integreren en de integraal komt terug. Kies $h'(x) = \mathrm{e}^{-x}$, dus $h(x) = -\mathrm{e}^{-x}$, en $g(x) = \cos(x)$, dus $g'(x) = -\sin(x)$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \mathrm{e}^{-x}\cos(x)$, de $x$-as en de $y$-as, op $\left[0, \tfrac{1}{2}\pi\right]$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Na twee rondes staat er $I = -\mathrm{e}^{-x}\cos(x) + \mathrm{e}^{-x}\sin(x) - I$. Noem de gevraagde integraal $I$. Na twee rondes staat $I$ rechts ook weer, dus je lost $I$ op zoals een vergelijking: alles met $I$ naar links, daarna delen. Uit $2I = \mathrm{e}^{-x}\left(\sin(x) - \cos(x)\right)$ volgt $F(x) = \tfrac{1}{2}\mathrm{e}^{-x}\left(\sin(x) - \cos(x)\right)$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \mathrm{e}^{-x}\cos(x)$, de $x$-as en de $y$-as, op $\left[0, \tfrac{1}{2}\pi\right]$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Vul de grenzen in: $F\left(\tfrac{1}{2}\pi\right) = \tfrac{1}{2}\mathrm{e}^{-\frac{1}{2}\pi}(1 - 0) = \tfrac{1}{2}\mathrm{e}^{-\frac{1}{2}\pi}$ en $F(0) = \tfrac{1}{2}(0 - 1) = -\tfrac{1}{2}$. De oppervlakte is $\tfrac{1}{2}\mathrm{e}^{-\frac{1}{2}\pi} + \tfrac{1}{2}$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ ligt tussen de grafiek van $f(x) = x^{2}\cos(x)$ en de $x$-as op $\left[\tfrac{1}{2}\pi, \pi\right]$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1 van de driedeling: op $\left[\tfrac{1}{2}\pi, \pi\right]$ is $\cos(x) \leq 0$ en $x^{2} > 0$, dus de grafiek ligt ónder de $x$-as. De oppervlakte is dan $-\displaystyle\int_{\frac{1}{2}\pi}^{\pi} x^{2}\cos(x)\,\mathrm{d}x$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ ligt tussen de grafiek van $f(x) = x^{2}\cos(x)$ en de $x$-as op $\left[\tfrac{1}{2}\pi, \pi\right]$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Deel 2: een veelterm van graad 2 maal een gonio → twee keer partieel integreren. Eerste ronde met $h'(x) = \cos(x)$, dus $h(x) = \sin(x)$, en $g(x) = x^{2}$: $\int x^{2}\cos(x)\,\mathrm{d}x = x^{2}\sin(x) - \int 2x\sin(x)\,\mathrm{d}x$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ ligt tussen de grafiek van $f(x) = x^{2}\cos(x)$ en de $x$-as op $\left[\tfrac{1}{2}\pi, \pi\right]$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Tweede ronde op $\int 2x\sin(x)\,\mathrm{d}x = -2x\cos(x) + 2\sin(x)$. De primitieve is $F(x) = x^{2}\sin(x) + 2x\cos(x) - 2\sin(x)$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ ligt tussen de grafiek van $f(x) = x^{2}\cos(x)$ en de $x$-as op $\left[\tfrac{1}{2}\pi, \pi\right]$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Vul de grenzen in: $F(\pi) = 0 - 2\pi - 0 = -2\pi$ en $F\left(\tfrac{1}{2}\pi\right) = \tfrac{1}{4}\pi^{2} + 0 - 2$. De integraal is $-2\pi - \tfrac{1}{4}\pi^{2} + 2$, en dat is negatief. De oppervlakte is het tegengestelde: $\tfrac{1}{4}\pi^{2} + 2\pi - 2$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$De grafiek van $f(x) = \left(x^{2} + 2x\right)\mathrm{e}^{x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $4\mathrm{e}^{2}$. Bereken exact $p$.$ksql$, 0, $ksql$Deel 1 van de driedeling: $f(x) = x(x + 2)\mathrm{e}^{x}$ snijdt de $x$-as bij $x = 0$ en $x = -2$. Voor $x > 0$ ligt de grafiek erboven, dus de oppervlakte is $\displaystyle\int_{0}^{p} \left(x^{2} + 2x\right)\mathrm{e}^{x}\,\mathrm{d}x$, en die moet $4\mathrm{e}^{2}$ worden.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$De grafiek van $f(x) = \left(x^{2} + 2x\right)\mathrm{e}^{x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $4\mathrm{e}^{2}$. Bereken exact $p$.$ksql$, 1, $ksql$Deel 2: een veelterm van graad 2 maal een e-macht → twee keer partieel integreren. Eerste ronde met $h'(x) = \mathrm{e}^{x}$ en $g(x) = x^{2} + 2x$, dus $g'(x) = 2x + 2$: er blijft $\int (2x + 2)\mathrm{e}^{x}\,\mathrm{d}x$ over.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$De grafiek van $f(x) = \left(x^{2} + 2x\right)\mathrm{e}^{x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $4\mathrm{e}^{2}$. Bereken exact $p$.$ksql$, 2, $ksql$Tweede ronde op $\int (2x + 2)\mathrm{e}^{x}\,\mathrm{d}x = (2x + 2)\mathrm{e}^{x} - 2\mathrm{e}^{x} = 2x\mathrm{e}^{x}$. Dus $F(x) = \left(x^{2} + 2x\right)\mathrm{e}^{x} - 2x\mathrm{e}^{x} = x^{2}\mathrm{e}^{x}$. Invullen van de grenzen geeft $\left[x^{2}\mathrm{e}^{x}\right]_{0}^{p} = p^{2}\mathrm{e}^{p}$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$De grafiek van $f(x) = \left(x^{2} + 2x\right)\mathrm{e}^{x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $4\mathrm{e}^{2}$. Bereken exact $p$.$ksql$, 3, $ksql$Deel 3: los de vergelijking op. Uit $p^{2}\mathrm{e}^{p} = 4\mathrm{e}^{2}$ zie je dat $p = 2$ voldoet, want $2^{2}\mathrm{e}^{2} = 4\mathrm{e}^{2}$. Omdat $p^{2}\mathrm{e}^{p}$ voor $p > 0$ alleen maar stijgt, is dat de enige oplossing: $p = 2$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \left(x^{2} - 1\right)\mathrm{e}^{x}$ en de $x$-as. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1 van de driedeling: $\mathrm{e}^{x}$ is nooit nul, dus de grafiek snijdt de $x$-as waar $x^{2} - 1 = 0$, dus bij $x = -1$ en $x = 1$. Daartussen is $x^{2} - 1$ negatief, dus ligt de grafiek ónder de $x$-as. De oppervlakte is $-\displaystyle\int_{-1}^{1} \left(x^{2} - 1\right)\mathrm{e}^{x}\,\mathrm{d}x$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \left(x^{2} - 1\right)\mathrm{e}^{x}$ en de $x$-as. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Deel 2: een veelterm van graad 2 maal een e-macht → twee keer partieel integreren. Eerste ronde met $h'(x) = \mathrm{e}^{x}$ en $g(x) = x^{2} - 1$, dus $g'(x) = 2x$: $\int \left(x^{2} - 1\right)\mathrm{e}^{x}\,\mathrm{d}x = \left(x^{2} - 1\right)\mathrm{e}^{x} - \int 2x\mathrm{e}^{x}\,\mathrm{d}x$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \left(x^{2} - 1\right)\mathrm{e}^{x}$ en de $x$-as. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Tweede ronde op $\int 2x\mathrm{e}^{x}\,\mathrm{d}x = 2x\mathrm{e}^{x} - 2\mathrm{e}^{x}$. Dus $F(x) = \left(x^{2} - 2x + 1\right)\mathrm{e}^{x} = (x - 1)^{2}\mathrm{e}^{x}$. Controle: differentiëren geeft $2(x - 1)\mathrm{e}^{x} + (x - 1)^{2}\mathrm{e}^{x} = (x - 1)(x + 1)\mathrm{e}^{x} = \left(x^{2} - 1\right)\mathrm{e}^{x}$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \left(x^{2} - 1\right)\mathrm{e}^{x}$ en de $x$-as. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Vul de grenzen in: $F(1) = 0$ en $F(-1) = 4\mathrm{e}^{-1} = \dfrac{4}{\mathrm{e}}$. De integraal is $0 - \dfrac{4}{\mathrm{e}} = -\dfrac{4}{\mathrm{e}}$, dus negatief. De oppervlakte is het tegengestelde: $\dfrac{4}{\mathrm{e}}$.$ksql$)
) AS v(topic_slug, cluster_slug, latex_body, step_order, step_description)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
JOIN public.questions_new vr ON vr.latex_body = v.latex_body AND vr.cluster_id = cl.id
ON CONFLICT (question_id, step_order) DO NOTHING;

-- 6. Controle
DO $do$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k2b_kwadraat_gonio' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k2b_herhaald' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k2b_kwadraat_gonio hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k2b_kwadraat_e' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k2b_herhaald' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k2b_kwadraat_e hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k2b_terugkomen' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k2b_herhaald' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k2b_terugkomen hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k2b_bepaald_kwadraat' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k2b_bepaald' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k2b_bepaald_kwadraat hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k2b_bepaald_terugkomen' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k2b_bepaald' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k2b_bepaald_terugkomen hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k2b_opp' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k2b_toepassingen' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k2b_opp hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.question_steps_new s
  JOIN public.questions_new vr ON vr.id = s.question_id
  JOIN public.topics_new t ON t.id = vr.topic_id
  WHERE t.site = 'integralen' AND t.slug IN ('k2b_herhaald', 'k2b_bepaald', 'k2b_toepassingen');
  IF n <> 144 THEN RAISE EXCEPTION 'Deze topics horen samen 144 stappen te hebben, gevonden %', n; END IF;
END $do$;

COMMIT;
